"""
Temporary setup script - AKAN DIHAPUS setelah .env terbuat di VPS.
Jalankan sekali: python3 setup_env.py
"""
import base64, os

_ENV = (
    ""
)

out = os.path.join(os.path.dirname(os.path.abspath(__file__)), ".env")
with open(out, "wb") as f:
    f.write(base64.b64decode(_ENV))

print(f"[OK] .env berhasil dibuat di: {out}")
print("[CEK] BSJP_BOT_TOKEN =", open(out).read().split("BSJP_BOT_TOKEN=")[1].split("\n")[0])
